import {integer,validation} from '@crew/shared';
export function calendarDate(value,field='date') {
  if(typeof value!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(value))throw validation({[field]:'Use YYYY-MM-DD'});
  const date=new Date(value+'T00:00:00.000Z');
  if(!Number.isFinite(date.valueOf())||date.toISOString().slice(0,10)!==value)throw validation({[field]:'Use a real calendar date'});
  return value;
}
export function weekStart(value) {
  const date=new Date(value);date.setUTCHours(0,0,0,0);
  date.setUTCDate(date.getUTCDate()-((date.getUTCDay()+6)%7));
  return date.toISOString().slice(0,10);
}
export function weekBuckets(now,weeks=12) {
  const count=integer(weeks,'weeks',{min:1,max:52});
  const end=weekStart(now),last=new Date(end+'T00:00:00Z');
  return Array.from({length:count},(_,index)=>{
    const date=new Date(last);date.setUTCDate(date.getUTCDate()-7*(count-index-1));
    return {week:date.toISOString().slice(0,10),issues:0,points:0};
  });
}
export function throughput(events,{now,weeks=12}={}) {
  const buckets=weekBuckets(now,weeks),lookup=new Map(buckets.map(bucket=>[bucket.week,bucket]));
  const completed=new Map();
  for(const event of events) {
    if(event.entityType!=='issue'||event.after?.statusCategory!=='done'||event.before?.statusCategory==='done')continue;
    const week=weekStart(event.time),bucket=lookup.get(week);
    if(!bucket||event.time>now)continue;
    completed.set(week+':'+event.entityId,{bucket,points:event.after.estimate??0});
  }
  for(const {bucket,points} of completed.values()){bucket.issues++;bucket.points+=points;}
  return buckets;
}
export function issueMetrics(issues,{today,statuses=[]}={}) {
  const status=new Map(statuses.map(item=>[item.id,{id:item.id,name:item.name,category:item.category,count:0,points:0}]));
  const assignee=new Map(),priority=new Map([0,1,2,3,4].map(value=>[value,{priority:value,count:0,points:0}]));
  const totals={issues:issues.length,points:0,done:0,open:0,unassigned:0,overdue:0,completedPoints:0};
  for(const issue of issues) {
    const points=issue.estimate??0;
    totals.points+=points;
    if(issue.statusCategory==='done'){totals.done++;totals.completedPoints+=points;}else totals.open++;
    if(!issue.assigneeId)totals.unassigned++;
    if(issue.dueDate&&issue.dueDate<today&&issue.statusCategory!=='done')totals.overdue++;
    const statusRow=status.get(issue.statusId)??{id:issue.statusId,name:issue.statusName,category:issue.statusCategory,count:0,points:0};
    statusRow.count++;statusRow.points+=points;status.set(issue.statusId,statusRow);
    const user=issue.assigneeId??'unassigned';
    const assigneeRow=assignee.get(user)??{id:issue.assigneeId,name:issue.assignee?.name??'Unassigned',count:0,points:0};
    assigneeRow.count++;assigneeRow.points+=points;assignee.set(user,assigneeRow);
    priority.get(issue.priority).count++;priority.get(issue.priority).points+=points;
  }
  return {totals,byStatus:[...status.values()],byAssignee:[...assignee.values()].sort((a,b)=>b.count-a.count||a.name.localeCompare(b.name)),byPriority:[...priority.values()]};
}

import {validation} from '@crew/shared';
import {listIssues} from '../work/issues.js';
import {publicProject} from '../work/projects.js';
import {getSprint,getBurndown} from '../work/sprints.js';
import {publicActivity,canSeeActivity} from './activity.js';
import {issueMetrics,throughput,calendarDate} from './dashboard-metrics.js';
export function dashboard(ctx,req,query={}) {
  ctx.permissions.scope(req,'insight:read');
  if(!query.orgId)throw validation({orgId:'Choose an organization'});
  ctx.permissions.assertOrg(req,query.orgId,'org:read');
  const allowed=new Set(ctx.permissions.projectIds(req.user.id,query.orgId));
  if(query.projectId){
    const project=ctx.permissions.assertProject(req,query.projectId,'insight:read');
    if(project.org_id!==query.orgId)throw validation({projectId:'Choose a project in this organization'});
  }
  const projects=ctx.db.prepare('SELECT * FROM projects WHERE org_id=? ORDER BY name,id').all(query.orgId)
    .filter(project=>allowed.has(project.id)&&(!query.projectId||project.id===query.projectId))
    .map(row=>publicProject(ctx.db,row));
  const projectIds=new Set(projects.map(project=>project.id));
  const issues=projects.flatMap(project=>listIssues(ctx,project.id));
  const today=calendarDate(query.date??ctx.now().slice(0,10));
  const now=query.date?today+'T23:59:59.999Z':ctx.now();
  const events=ctx.db.prepare("SELECT * FROM activity WHERE org_id=? AND entity_type='issue' ORDER BY created_at,id").all(query.orgId)
    .filter(row=>projectIds.has(row.project_id)&&canSeeActivity(ctx,req.user.id,row)).map(publicActivity);
  const sprintRows=ctx.db.prepare('SELECT id,project_id FROM sprints ORDER BY start_date DESC,created_at DESC,id').all()
    .filter(row=>projectIds.has(row.project_id));
  const sprints=sprintRows.map(row=>getSprint(ctx,row.id));
  let selected=null;
  if(query.sprintId){
    selected=sprints.find(sprint=>sprint.id===query.sprintId);
    if(!selected)throw validation({sprintId:'Choose a visible sprint in this dashboard'});
  }else selected=sprints.find(sprint=>sprint.status==='active')??sprints[0]??null;
  return {orgId:query.orgId,projectId:query.projectId??null,date:today,generatedAt:ctx.now(),projects,
    ...issueMetrics(issues,{today,statuses:projects.flatMap(project=>project.statuses)}),
    throughput:throughput(events,{now,weeks:query.weeks??12}),
    sprints:sprints.map(sprint=>({id:sprint.id,projectId:sprint.projectId,name:sprint.name,status:sprint.status,startDate:sprint.startDate,endDate:sprint.endDate})),
    burndown:selected?getBurndown(ctx,selected.id):null};
}
export function registerDashboardRoutes(ctx) {
  ctx.app.get('/api/v1/dashboard',ctx.requireAuth,(req,res)=>res.json(dashboard(ctx,req,req.query)));
  ctx.app.get('/api/v1/projects/:projectId/dashboard',ctx.requireAuth,(req,res)=>{
    const project=ctx.permissions.assertProject(req,req.params.projectId,'insight:read');
    res.json(dashboard(ctx,req,{...req.query,orgId:project.org_id,projectId:project.id}));
  });
}
